<script setup>
import {ref} from 'vue';import {session,request} from './api'
const items=ref([]),reasons=ref({}),actor=ref('')
async function refresh(){const r=await request('/api/approvals');if(r.status==='ok')items.value=r.answer}
async function decide(item,approved){await request(`/api/approvals/${encodeURIComponent(item.id)}/decide`,{version:item.version,payload_hash:item.payload_hash,approved,actor:actor.value,reason:reasons.value[item.id]||''},{approval:true});await refresh()}
</script>
<template><section class="panel"><p class="eyebrow">제안 → 사람의 결정 → 기록</p><h2>무엇을 승인하는지 먼저 확인합니다</h2><div class="form-row"><label>판단자 역할<input v-model="actor"/></label><label>사람 승인용 토큰<input type="password" v-model="session.approver" autocomplete="off"/></label><button @click="refresh" :disabled="session.busy">승인 목록 새로고침</button></div><article v-for="item in items" :key="item.id" class="evidence"><h3>{{item.status}} · 제안 {{item.id}}</h3><p>{{item.payload.rationale}}</p><p>규칙 {{item.payload.rule_id}} / 기존 버전 {{item.payload.expected_rule_version}} → 새 폭 {{item.payload.new_width}}</p><small>{{item.payload.action_scope}}</small><details><summary>제안 근거와 내용 확인</summary><pre>{{JSON.stringify(item.payload,null,2)}}</pre></details><label v-if="item.status==='pending_approval'">판단 사유<textarea v-model="reasons[item.id]"/></label><div class="actions" v-if="item.status==='pending_approval'"><button :disabled="session.busy||!actor||!reasons[item.id]" @click="decide(item,true)">이 제안 승인</button><button :disabled="session.busy||!actor||!reasons[item.id]" @click="decide(item,false)">반려</button></div><p v-else>{{item.reason}}</p></article></section></template>
